/**
 * Prints the `insert into public.avatars` seed for the shipped owner avatars
 * (IMAGE_AVATARS, generated by import-avatars.ts), as used in migration
 * 089_avatars_library.sql. Their files stay where they ship, as static paths
 * (/avatars/<id>-96.webp?v=…); the avatars bucket only holds new uploads.
 *
 *   npx tsx scripts/avatars/seed-sql.ts
 */
import { pathToFileURL } from 'node:url';
import { IMAGE_AVATARS } from '../../src/components/stage/avatars/images.generated';

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;

export function seedSql(): string {
  const rows = IMAGE_AVATARS.map((a, i) =>
    `  (${q(a.id)}, ${q(a.title.en)}, ${q(a.title.el)}, ${q(a.thumb)}, ${q(a.full)}, ${q(a.hidden ? 'unpublished' : 'published')}, ${(i + 1) * 10})`);
  return [
    'insert into public.avatars (id, title_en, title_el, thumb_path, full_path, status, sort) values',
    rows.join(',\n'),
    'on conflict (id) do nothing;',
  ].join('\n');
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) console.log(seedSql());
